at::Tensor tall_skinny_matmul_impl_npu(const at::Tensor& A, const at::Tensor& B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Only 2D matrices are supported");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible shapes for matmul: (", A.size(0), ",", A.size(1),
                ") x (", B.size(0), ",", B.size(1), ")");
    int64_t m = A.size(0);
    int64_t n = B.size(1);
    at::Tensor result = at::empty({m, n}, A.options());
    EXEC_NPU_CMD(aclnnTallSkinnyMatrixMultiplicationCustom, A, B, result);
    return result;
}

